-- 查找管理员用户ID与教师ID
SET @admin_user_id = (SELECT id FROM users WHERE role_name = 'SUPER_ADMIN' ORDER BY id LIMIT 1);
SET @admin_user_id = COALESCE(@admin_user_id, (SELECT id FROM users WHERE role_name = 'ADMIN' ORDER BY id LIMIT 1));
SET @admin_user_id = COALESCE(@admin_user_id, (SELECT id FROM users WHERE role_name IN ('TEACHER','HEAD_TEACHER') ORDER BY id LIMIT 1));
SET @admin_teacher_id = (SELECT id FROM teachers WHERE user_id = @admin_user_id LIMIT 1);
SET @admin_teacher_id = COALESCE(@admin_teacher_id, (SELECT id FROM teachers ORDER BY id LIMIT 1));

SELECT CONCAT('[V051] 开始注入，管理员ID: ', COALESCE(@admin_user_id, 0), ', 教师ID: ', COALESCE(@admin_teacher_id, 0)) AS info;

