VALUES ('文字处理基础操作实训 01', '【图文编辑】 打开文档“将进酒.docx”，按下列要求设置、编排文档格式。', '办公应用基础', 'office', '[{"title": "第1步：删除文中“君不见，黄河之水天上来，奔流到海不复回。”至“译文”中的空段落。", "type": "office", "description": "删除文中“君不见，黄河之水天上来，奔流到海不复回。”至“译文”中的空段落。", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_01.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_01_____1.png"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：将文档标题“将进酒”的字体设置为华文行楷，字号为初号，并为其添加“填充-橙色，强", "type": "office", "description": "将文档标题“将进酒”的字体设置为华文行楷，字号为初号，并为其添加“填充-橙色，强调文字颜色6，渐变轮廓-强调文字颜色6”的文本效果，居中对齐。", "score": {"max": 3, "min": 0}}, {"title": "第3步：将文档第1段的字体设置为华文行楷，字号为三号，字体颜色为标准色中的“深蓝”色，居", "type": "office", "description": "将文档第1段的字体设置为华文行楷，字号为三号，字体颜色为标准色中的“深蓝”色，居中对齐。", "score": {"max": 2, "min": 0}}, {"title": "第4步：将正文从“君不见，黄河之水天上来，奔流到海不复回。”至“与尔同销万古愁。”的字体", "type": "office", "description": "将正文从“君不见，黄河之水天上来，奔流到海不复回。”至“与尔同销万古愁。”的字体设置为仿宋_GB2312，字号为四号，加粗。首行缩进2个字符，段落间距为段前段后各0.5行，行距为1.5倍行距。", "score": {"max": 4, "min": 0}}, {"title": "第5步：为文中的“樽、岑、馔、恣、谑、沽、酌、裘“七个字添加拼音。", "type": "office", "description": "为文中的“樽、岑、馔、恣、谑、沽、酌、裘“七个字添加拼音。", "score": {"max": 4, "min": 0}}, {"title": "第6步：将“译文”和“赏析”及其包含的段落文本的字体设置为华文细黑，字号为小四，设置行距", "type": "office", "description": "将“译文”和“赏析”及其包含的段落文本的字体设置为华文细黑，字号为小四，设置行距为固定值20磅，首行缩进2字符，并将文本“译文”和“赏析”设为深蓝色，加粗，并添加深蓝色双下划线。", "score": {"max": 4, "min": 0}}, {"title": "第7步：在文中插入“{{QuestionDir}}”下的图片“李白.jpg”，将其颜色重", "type": "office", "description": "在文中插入“{{QuestionDir}}”下的图片“李白.jpg”，将其颜色重新着色为“茶色，背景颜色2浅色”，环绕方式为“衬于文字下方”，置于样文中所示位置。", "score": {"max": 4, "min": 0}}, {"title": "第8步：在“唐·李白”后添脚注，内容为“李白(701-762)，字太白，号青莲居士，唐朝", "type": "office", "description": "在“唐·李白”后添脚注，内容为“李白(701-762)，字太白，号青莲居士，唐朝浪漫主义诗人，被后人誉为“诗仙”。汉族，祖籍陇西成纪，出生于碎叶城（当时属唐朝领土，今属吉尔吉斯斯坦），4岁再随父迁至剑南道绵州。李白存世诗文千余篇，有《李太白集》传世。762年病逝，享年61岁。”", "score": {"max": 2, "min": 0}}, {"title": "第9步：为文档添加页眉“古诗欣赏”，字体为华文行楷，小四号，左对齐。使用“奥斯汀”页脚。", "type": "office", "description": "为文档添加页眉“古诗欣赏”，字体为华文行楷，小四号，左对齐。使用“奥斯汀”页脚。", "score": {"max": 3, "min": 0}}, {"title": "第10步：为页面添加2.25磅三维边框。（2分）请参看样张：样张", "type": "office", "description": "为页面添加2.25磅三维边框。（2分）请参看样张：样张", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

