VALUES ('文字处理基础操作实训 02', '【图文编辑】 打开文档“WORD.docx”，按下列要求设置、编排文档格式。', '办公应用基础', 'office', '[{"title": "第1步：设置纸张大小为B5（18.2厘米*25.7厘米），对称页边距，上、下页边距为2.", "type": "office", "description": "设置纸张大小为B5（18.2厘米*25.7厘米），对称页边距，上、下页边距为2.5厘米，内侧页边距3厘米、外侧页边距为2.5厘米。", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_02.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_02_____1.png", "/api/uploads/practice/文字处理基础/op_02_____2.png"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：将正文设置为五号仿宋，首行缩进2字符，1.3倍行距。", "type": "office", "description": "将正文设置为五号仿宋，首行缩进2字符，1.3倍行距。", "score": {"max": 3, "min": 0}}, {"title": "第3步：按样文所示，在文档的页眉处添加页眉文字：民俗民风大全，黑体，五号字，居中对齐；页", "type": "office", "description": "按样文所示，在文档的页眉处添加页眉文字：民俗民风大全，黑体，五号字，居中对齐；页脚处添加页码，样式为“-1-”奇数页右对齐，偶数页左对齐。", "score": {"max": 3, "min": 0}}, {"title": "第4步：将标题“中秋：月辉中的文化长卷与情感纽带”设置为艺术字样式“填充-橄榄色，强调文", "type": "office", "description": "将标题“中秋：月辉中的文化长卷与情感纽带”设置为艺术字样式“填充-橄榄色，强调文字颜色3，粉状棱台”；字体为华文中宋、加粗，字号为三号字，文字环绕方式为“上下型环绕”，对齐方式为居中；为艺术字添加“紧密映像，4pt偏移量”的文本效果。", "score": {"max": 6, "min": 0}}, {"title": "第5步：将正文中各小标题设置为黑体，四号字。", "type": "office", "description": "将正文中各小标题设置为黑体，四号字。", "score": {"max": 3, "min": 0}}, {"title": "第6步：将正文第二段至倒数第二段分为2栏。", "type": "office", "description": "将正文第二段至倒数第二段分为2栏。", "score": {"max": 2, "min": 0}}, {"title": "第7步：为正文的第一段添加1.5磅、深绿色(RGB：100，120，50)、双实线边框，", "type": "office", "description": "为正文的第一段添加1.5磅、深绿色(RGB：100，120，50)、双实线边框，并为其填充绿色(RGB：160，200，120)底纹。", "score": {"max": 4, "min": 0}}, {"title": "第8步：在正文第二段中插入“{{QuestionDir}}”下的图片“赏月.jpg”，环", "type": "office", "description": "在正文第二段中插入“{{QuestionDir}}”下的图片“赏月.jpg”，环绕方式为“紧密型环绕”，并为图片添加“映像圆角矩形“的外观样式。", "score": {"max": 3, "min": 0}}, {"title": "第9步：为正文第一段中的：海上生明月，天涯共此时。插入脚注“本诗出自唐代诗人张九龄的《望", "type": "office", "description": "为正文第一段中的：海上生明月，天涯共此时。插入脚注“本诗出自唐代诗人张九龄的《望月怀远》。”。（3分）请参看样张：样张1样张2", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

