VALUES ('文字处理基础操作实训 07', '请在打开的窗口中，进行下列操作，完成所有操作后，请关闭窗口。', '办公应用基础', 'office', '[{"title": "第1步：将页面设置为：上、下、左、右页边距均为3厘米；指定行和字符网格，其中每行38个字", "type": "office", "description": "将页面设置为：上、下、左、右页边距均为3厘米；指定行和字符网格，其中每行38个字符，每页40行；", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_07.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_07_____1.jpg", "/api/uploads/practice/文字处理基础/op_07_____2.jpg"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：将文中所有“智能家具”替换成“智能家居”；", "type": "office", "description": "将文中所有“智能家具”替换成“智能家居”；", "score": {"max": 2, "min": 0}}, {"title": "第3步：将文章标题“智能家居”设置为黑体、二号字、加粗、标准色：深蓝色、字符间距加宽6磅", "type": "office", "description": "将文章标题“智能家居”设置为黑体、二号字、加粗、标准色：深蓝色、字符间距加宽6磅，居中显示；", "score": {"max": 3, "min": 0}}, {"title": "第4步：设置标题行距为固定值25磅，设置正文行距为1.5倍行距；", "type": "office", "description": "设置标题行距为固定值25磅，设置正文行距为1.5倍行距；", "score": {"max": 2, "min": 0}}, {"title": "第5步：设置正文第一段首字下沉2行，首字字体为幼圆；", "type": "office", "description": "设置正文第一段首字下沉2行，首字字体为幼圆；", "score": {"max": 3, "min": 0}}, {"title": "第6步：参考样张，同时选中正文中四段加粗显示的小标题，为其添加编号，编号格式为“1、 2", "type": "office", "description": "参考样张，同时选中正文中四段加粗显示的小标题，为其添加编号，编号格式为“1、 2、 3、 ……”；", "score": {"max": 2, "min": 0}}, {"title": "第7步：参考样张，同时选中正文中四段加粗显示的小标题文字，为其设置映像效果为“紧密映像：", "type": "office", "description": "参考样张，同时选中正文中四段加粗显示的小标题文字，为其设置映像效果为“紧密映像：接触”，并为其添加1.5磅、标准色-蓝色、带阴影的文字边框；", "score": {"max": 4, "min": 0}}, {"title": "第8步：参照样张，为文档添加宋体、斜式、半透明文字水印效果“考试专用”；", "type": "office", "description": "参照样张，为文档添加宋体、斜式、半透明文字水印效果“考试专用”；", "score": {"max": 4, "min": 0}}, {"title": "第9步：参照样张，将四个时期所在4个段落转换一个4行2列的表格；", "type": "office", "description": "参照样张，将四个时期所在4个段落转换一个4行2列的表格；", "score": {"max": 2, "min": 0}}, {"title": "第10步：将表格中的所有文字设置为靠上居中对齐，套用“浅色底纹-强调文字颜色5”表格样式；", "type": "office", "description": "将表格中的所有文字设置为靠上居中对齐，套用“浅色底纹-强调文字颜色5”表格样式；", "score": {"max": 2, "min": 0}}, {"title": "第11步：设置奇数页页眉为“智慧生活”，偶数页页眉为“创造未来”，均为右对齐，并在所有页面", "type": "office", "description": "设置奇数页页眉为“智慧生活”，偶数页页眉为“创造未来”，均为右对齐，并在所有页面（奇偶页都插入）的底端插入页码，页码样式为“标签1”。", "score": {"max": 4, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

