VALUES ('文字处理基础操作实训 08', '请在打开的窗口中，进行下列操作，完成所有操作后，请关闭窗口。', '办公应用基础', 'office', '[{"title": "第1步：将页面设置为：A4纸，上、下页边距为3.5厘米，左、右页边距为3.1厘米，每页4", "type": "office", "description": "将页面设置为：A4纸，上、下页边距为3.5厘米，左、右页边距为3.1厘米，每页40行，每行35个字符；", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_08.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_08_____1.jpg", "/api/uploads/practice/文字处理基础/op_08_____2.jpg"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：设置标题字体为华文行楷、一号字、加粗、蓝色（标准色），段前段后间距均为0.5行，", "type": "office", "description": "设置标题字体为华文行楷、一号字、加粗、蓝色（标准色），段前段后间距均为0.5行，居中显示；", "score": {"max": 4, "min": 0}}, {"title": "第3步：将正文第二段加上1.5磅带阴影的红色单实线边框，填充底纹颜色为白色，背景1，深色", "type": "office", "description": "将正文第二段加上1.5磅带阴影的红色单实线边框，填充底纹颜色为白色，背景1，深色15% ；", "score": {"max": 3, "min": 0}}, {"title": "第4步：在正文插入竖排文本框“粮油价格持续上涨”，设置字体格式为黑体、二号（参照样张）；", "type": "office", "description": "在正文插入竖排文本框“粮油价格持续上涨”，设置字体格式为黑体、二号（参照样张）；", "score": {"max": 2, "min": 0}}, {"title": "第5步：设置文本框边框为“无轮廓”，环绕方式为四周型，对齐方式为右对齐，文本框高度为7.", "type": "office", "description": "设置文本框边框为“无轮廓”，环绕方式为四周型，对齐方式为右对齐，文本框高度为7.5厘米，宽度为1.8厘米；", "score": {"max": 3, "min": 0}}, {"title": "第6步：在第1页适当位置插入形状“云形标注”，设置形状的高度为4厘米、宽度为6厘米；", "type": "office", "description": "在第1页适当位置插入形状“云形标注”，设置形状的高度为4厘米、宽度为6厘米；", "score": {"max": 3, "min": 0}}, {"title": "第7步：设置形状“云形标注”的填充为“{{QuestionDir}}”下的图片“粮油.j", "type": "office", "description": "设置形状“云形标注”的填充为“{{QuestionDir}}”下的图片“粮油.jpg”，线条颜色为紫色（标准色），环绕方式为紧密型；", "score": {"max": 3, "min": 0}}, {"title": "第8步：将文章倒数第一段“中国的一般收入人群……股份制农场。”分为等宽两栏，栏间加分隔线", "type": "office", "description": "将文章倒数第一段“中国的一般收入人群……股份制农场。”分为等宽两栏，栏间加分隔线；", "score": {"max": 3, "min": 0}}, {"title": "第9步：在页面底端插入页码，页码格式为“-1-”，对齐方式为居中 ；", "type": "office", "description": "在页面底端插入页码，页码格式为“-1-”，对齐方式为居中 ；", "score": {"max": 2, "min": 0}}, {"title": "第10步：将表格外框线设置为红色（标准色）0.75磅双实线，设置表格的对齐方式为居中；", "type": "office", "description": "将表格外框线设置为红色（标准色）0.75磅双实线，设置表格的对齐方式为居中；", "score": {"max": 2, "min": 0}}, {"title": "第11步：在表格最后一行中计算购买各地区物品所需价格的总计。", "type": "office", "description": "在表格最后一行中计算购买各地区物品所需价格的总计。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

