VALUES ('文字处理基础操作实训 09', '请在打开的窗口中，进行下列操作，完成所有操作后，请关闭窗口。', '办公应用基础', 'office', '[{"title": "第1步：设置页面颜色为“金色，强调文字颜色4，淡色80%”，纸张大小为“自定义大小”，高", "type": "office", "description": "设置页面颜色为“金色，强调文字颜色4，淡色80%”，纸张大小为“自定义大小”，高度为“26”，宽度为“20”；", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_09.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_09_____1.jpg", "/api/uploads/practice/文字处理基础/op_09_____2.jpg"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：设置文档上下页边距为“1.8厘米”，页码范围为“对称页边距”，指定行和字符网格每", "type": "office", "description": "设置文档上下页边距为“1.8厘米”，页码范围为“对称页边距”，指定行和字符网格每行40字符，每页34行；", "score": {"max": 2, "min": 0}}, {"title": "第3步：设置标题格式为“隶书、一号、加粗、居中”，以青绿色突出显示；", "type": "office", "description": "设置标题格式为“隶书、一号、加粗、居中”，以青绿色突出显示；", "score": {"max": 3, "min": 0}}, {"title": "第4步：将文中所有“肺炎”设置为“加粗 倾斜、浅蓝”，添加着重号；", "type": "office", "description": "将文中所有“肺炎”设置为“加粗 倾斜、浅蓝”，添加着重号；", "score": {"max": 4, "min": 0}}, {"title": "第5步：将第四段（2020年8月……）分为3栏，1栏栏宽为11字符，栏距为1.5字符，添", "type": "office", "description": "将第四段（2020年8月……）分为3栏，1栏栏宽为11字符，栏距为1.5字符，添加分隔线；", "score": {"max": 3, "min": 0}}, {"title": "第6步：将第六段小标题（主要症状）添加边框“阴影”，底纹填充“橙色”，图案样式为“5%”", "type": "office", "description": "将第六段小标题（主要症状）添加边框“阴影”，底纹填充“橙色”，图案样式为“5%”，均应用于文字，参考样张添加符号（Wingdings：118）；", "score": {"max": 4, "min": 0}}, {"title": "第7步：使用格式刷将第六段小标题应用到第九、十七段，并将文中添加着重号的小标题插入“1，", "type": "office", "description": "使用格式刷将第六段小标题应用到第九、十七段，并将文中添加着重号的小标题插入“1，2，3…”，格式为“1、”的编号；", "score": {"max": 3, "min": 0}}, {"title": "第8步：为文中倒数第六段（是指……）中“气溶胶”插入脚注，内容为“由固体或液体小质点，分", "type": "office", "description": "为文中倒数第六段（是指……）中“气溶胶”插入脚注，内容为“由固体或液体小质点，分散并悬浮在气体介质中，形成的胶体分散体系。”；", "score": {"max": 2, "min": 0}}, {"title": "第9步：设置文章末尾图片宽度与高度均为“2.5厘米”，图片右侧页边距水平位置“12.6厘", "type": "office", "description": "设置文章末尾图片宽度与高度均为“2.5厘米”，图片右侧页边距水平位置“12.6厘米”，下侧页边距垂直位置“19厘米”，图片重新着色为“冲蚀”；", "score": {"max": 3, "min": 0}}, {"title": "第10步：为文档插入页眉，设置奇偶页不同，奇数页内容为“戴口罩，勤洗手，测体温”，偶数页内", "type": "office", "description": "为文档插入页眉，设置奇偶页不同，奇数页内容为“戴口罩，勤洗手，测体温”，偶数页内容为“勤消毒，少聚集，勤通风”，均为右对齐。", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

