VALUES ('文字处理基础操作实训 17', '【图文编辑】 打开“{{QuestionDir}}”文件夹中的“WORD.docx”，按下列要求进行图文编辑。', '办公应用基础', 'office', '[{"title": "第1步：将文档主题设置为“跋涉”。", "type": "office", "description": "将文档主题设置为“跋涉”。", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_17.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_17_____1.png"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：将标题“锦官城里的璀璨星辰：成都历史名人录”设置为：方正粗倩简体（如没有该字体，", "type": "office", "description": "将标题“锦官城里的璀璨星辰：成都历史名人录”设置为：方正粗倩简体（如没有该字体，请自行安装），32磅，艺术字样式“填充-橙色，强调文字颜色6，暖色粗糙棱台”，环绕方式为上下型环绕，将标题中的“成都历史名人录”另起一段，艺术字样式转换“弯曲，停止”将艺术字置于页面上方中间位置。", "score": {"max": 4, "min": 0}}, {"title": "第3步：将正文所有文字设置为：华文楷体，小四号字，首行缩进2字符，行间距固定值24磅。", "type": "office", "description": "将正文所有文字设置为：华文楷体，小四号字，首行缩进2字符，行间距固定值24磅。", "score": {"max": 2, "min": 0}}, {"title": "第4步：将文中小标题“一、文学巨匠——司马相如”设为四号，加粗显示，并为其设置如下格式：", "type": "office", "description": "将文中小标题“一、文学巨匠——司马相如”设为四号，加粗显示，并为其设置如下格式：深蓝色，1.5磅，双实线边框；填充：褐色，强调文字颜色2，淡色80%（RGB：237,223,218），图案样式12.5%，并将该格式应用到其他小标题。", "score": {"max": 5, "min": 0}}, {"title": "第5步：插入图片“司马相如.jpg”，重新着色为“冲蚀”，将其置于样文所示文字下方（先置", "type": "office", "description": "插入图片“司马相如.jpg”，重新着色为“冲蚀”，将其置于样文所示文字下方（先置于文字上方后，再置于文字下方）。", "score": {"max": 3, "min": 0}}, {"title": "第6步：将“二、史学大家——常璩”下的正文分为偏右两栏。", "type": "office", "description": "将“二、史学大家——常璩”下的正文分为偏右两栏。", "score": {"max": 2, "min": 0}}, {"title": "第7步：在“三、诗画双绝——黄筌”正文后面插入“{{QuestionDir}}”下的图片", "type": "office", "description": "在“三、诗画双绝——黄筌”正文后面插入“{{QuestionDir}}”下的图片“黄筌代表作.jpg”，上下型环绕，并插入题注“图1黄筌代表作”，文字居中对齐。", "score": {"max": 5, "min": 0}}, {"title": "第8步：将“五、女中豪杰——花蕊夫人“下的正文文字设置为在文本框内显示，文本框形状为“横", "type": "office", "description": "将“五、女中豪杰——花蕊夫人“下的正文文字设置为在文本框内显示，文本框形状为“横卷形”，使用形状样式：彩色轮廓-褐色，强调文字颜色3。修改文本框及卷轴位置，使所有文字都能显示。", "score": {"max": 5, "min": 0}}, {"title": "第9步：在页面底端中间插入页码：“滚动”。", "type": "office", "description": "在页面底端中间插入页码：“滚动”。", "score": {"max": 2, "min": 0}}, {"title": "第10步：将格式化后的“WORD.docx”另存为“成都历史名人.docx”。请参看样张：", "type": "office", "description": "将格式化后的“WORD.docx”另存为“成都历史名人.docx”。请参看样张：样张", "score": {"max": 10, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

