VALUES ('文字处理基础操作实训 19', '【图文编辑】 打开文档”Word素材.docx“文件，按下列要求进行图文编辑。', '办公应用基础', 'office', '[{"title": "第1步：将页面设置为A4，纵向，上下左右页边距均为2厘米。", "type": "office", "description": "将页面设置为A4，纵向，上下左右页边距均为2厘米。", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_19.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_19_____1.png"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "table", "desc": "表格操作正确", "expected": "true", "score": 6}]}}, {"title": "第2步：删除正文中的空行。", "type": "office", "description": "删除正文中的空行。", "score": {"max": 2, "min": 0}}, {"title": "第3步：将正文文字设置为楷体，五号字，首行缩进2字符，行间距1.3倍，段前、段后间距均为", "type": "office", "description": "将正文文字设置为楷体，五号字，首行缩进2字符，行间距1.3倍，段前、段后间距均为0.5行。", "score": {"max": 2, "min": 0}}, {"title": "第4步：去除表格中文本的段落格式设置：无首行缩进，行间距单倍行距，段前后前距无。为表格添", "type": "office", "description": "去除表格中文本的段落格式设置：无首行缩进，行间距单倍行距，段前后前距无。为表格添加样式：浅色网格，强调文字颜色3，表格第1行与第1、2列的的文字水平居中，其余单元格文字靠上两端对齐，重复标题行。", "score": {"max": 5, "min": 0}}, {"title": "第5步：将正文中所有“老舍”字样设置为：红色，强调文字颜色2（RGB：192，80，77", "type": "office", "description": "将正文中所有“老舍”字样设置为：红色，强调文字颜色2（RGB：192，80，77），加粗，加着重号。", "score": {"max": 2, "min": 0}}, {"title": "第6步：将标题“人民艺术家——老舍”设置为艺术字样式“填充紫色，强调文字颜色4，外部阴影", "type": "office", "description": "将标题“人民艺术家——老舍”设置为艺术字样式“填充紫色，强调文字颜色4，外部阴影，强调文字颜色4，软边缘棱台”，字体为华文新魏、加粗，字号48磅，文字环绕方式为上下型。绝对位置为：距右侧栏1.9厘米，距下侧段落0厘米。", "score": {"max": 4, "min": 0}}, {"title": "第7步：为正文第一段添加阴影边框，紫色，强调文字颜色4，淡色80%（RGB：229,22", "type": "office", "description": "为正文第一段添加阴影边框，紫色，强调文字颜色4，淡色80%（RGB：229,223,236），样式10%底纹。", "score": {"max": 3, "min": 0}}, {"title": "第8步：在正文中插入“{{QuestionDir}}”下的图片“老舍.jpg”。设置为高", "type": "office", "description": "在正文中插入“{{QuestionDir}}”下的图片“老舍.jpg”。设置为高8厘米，宽10.2厘米，四周型环绕，置于样稿中所示位置。", "score": {"max": 3, "min": 0}}, {"title": "第9步：为正文第5~7段设置分栏：三栏，栏间距4字符，加分隔线。", "type": "office", "description": "为正文第5~7段设置分栏：三栏，栏间距4字符，加分隔线。", "score": {"max": 3, "min": 0}}, {"title": "第10步：为正文第1段中的“老舍”添加脚注:“老舍(1899年2月3日——1966年8月2", "type": "office", "description": "为正文第1段中的“老舍”添加脚注:“老舍(1899年2月3日——1966年8月24日)，原名舒庆春，字舍予，另有笔名絜青、鸿来、非我等。他是中国现代小说家、剧作家、语言大师和人民艺术家，新中国第一位获得“人民艺术家”称号的作家。”", "score": {"max": 2, "min": 0}}, {"title": "第11步：为在第5段中的《骆驼祥子》添加批注：“现实主义力作，社会悲剧”。", "type": "office", "description": "为在第5段中的《骆驼祥子》添加批注：“现实主义力作，社会悲剧”。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

