VALUES ('文字处理基础操作实训 21', '请在打开的WORD的文档中，进行下列操作，完成操作后，请保存文档，并关闭WORD。', '办公应用基础', 'office', '[{"title": "第1步：在首行输入标题为“绿萝”，设置标题字体格式为“黑体、二号、绿色、居中对齐”", "type": "office", "description": "在首行输入标题为“绿萝”，设置标题字体格式为“黑体、二号、绿色、居中对齐”", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_21.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_21_o-Word-Word-10011_Title0.png"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：设置标题段落格式为“段前间距1行、段后间距0.5行”", "type": "office", "description": "设置标题段落格式为“段前间距1行、段后间距0.5行”", "score": {"max": 2, "min": 0}}, {"title": "第3步：将“品种分类”下面四个段落加项目符号，并设置项目符号的颜色为蓝色", "type": "office", "description": "将“品种分类”下面四个段落加项目符号，并设置项目符号的颜色为蓝色", "score": {"max": 2, "min": 0}}, {"title": "第4步：将正文第十段（蔓延下来的绿色……）连接在第九段末尾（绿萝是阴性植物，喜散射光，较", "type": "office", "description": "将正文第十段（蔓延下来的绿色……）连接在第九段末尾（绿萝是阴性植物，喜散射光，较……）形成一个完整的段落", "score": {"max": 2, "min": 0}}, {"title": "第5步：在文章末尾插入“{{QuestionDir}}”下的图片“绿萝.jpg”，并将图", "type": "office", "description": "在文章末尾插入“{{QuestionDir}}”下的图片“绿萝.jpg”，并将图片的宽高都缩放为原来的“45%”，设置其环绕方式为“浮于文字上方”", "score": {"max": 3, "min": 0}}, {"title": "第6步：使用“设置透明色”工具，将图片中的灰色背景设置为透明色", "type": "office", "description": "使用“设置透明色”工具，将图片中的灰色背景设置为透明色", "score": {"max": 3, "min": 0}}, {"title": "第7步：设置整篇文档的页面边框为“方框”，样式为“双实线、浅绿”、测量基准为“文字”", "type": "office", "description": "设置整篇文档的页面边框为“方框”，样式为“双实线、浅绿”、测量基准为“文字”", "score": {"max": 2, "min": 0}}, {"title": "第8步：在文章末尾处插入自选图形中的“立方体”，填充为“无填充颜色”，并将自选图形移动到", "type": "office", "description": "在文章末尾处插入自选图形中的“立方体”，填充为“无填充颜色”，并将自选图形移动到合适位置与图片进行组合", "score": {"max": 3, "min": 0}}, {"title": "第9步：将文档添加文字水印，内容为“绿萝