VALUES ('文字处理基础操作实训 40', '请在打开的WORD的文档中，进行下列操作，完成操作后，请保存文档，并关闭WORD。', '办公应用基础', 'office', '[{"title": "第1步：将文中所有错词“趋动”替换为“驱动”；", "type": "office", "description": "将文中所有错词“趋动”替换为“驱动”；", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/文字处理基础/op_40.docx", "sampleImages": ["/api/uploads/practice/文字处理基础/op_40_o-Word-Word-10010_Title0.png"], "config": {"checkpoints": [{"type": "page_setup", "desc": "页面设置正确", "expected": "true", "score": 5}, {"type": "font_format", "desc": "字体格式设置正确", "expected": "true", "score": 6}, {"type": "paragraph_format", "desc": "段落格式设置正确", "expected": "true", "score": 5}, {"type": "border_shading", "desc": "边框底纹设置正确", "expected": "true", "score": 4}, {"type": "header_footer", "desc": "页眉页脚设置正确", "expected": "true", "score": 4}]}}, {"title": "第2步：将标题“硬件管理”设置为“渐变填充-蓝色，强调文字颜色1”的艺术字，在页面水平居", "type": "office", "description": "将标题“硬件管理”设置为“渐变填充-蓝色，强调文字颜色1”的艺术字，在页面水平居中显示，环绕方式为“上下型”；", "score": {"max": 3, "min": 0}}, {"title": "第3步：将正文1-4段文字（“随着技术的发展和普及，......再按照安装程序的提示进行", "type": "office", "description": "将正文1-4段文字（“随着技术的发展和普及，......再按照安装程序的提示进行相应的操作即可。”）设置为四号字、中文字体为仿宋体，段落格式设置为段前间距0.5行、段后间距0.5行、行距为固定值28磅；", "score": {"max": 5, "min": 0}}, {"title": "第4步：正文第1段（“随着技术的发展和普及......进行正常通讯的程序。”）首字“下沉", "type": "office", "description": "正文第1段（“随着技术的发展和普及......进行正常通讯的程序。”）首字“下沉”3行；", "score": {"max": 1, "min": 0}}, {"title": "第5步：为正文第2段和第3段添加样式为的“1）、2）”编号；", "type": "office", "description": "为正文第2段和第3段添加样式为的“1）、2）”编号；", "score": {"max": 1, "min": 0}}, {"title": "第6步：设置文档的页边距为上、下2厘米，左、右2厘米；", "type": "office", "description": "设置文档的页边距为上、下2厘米，左、右2厘米；", "score": {"max": 2, "min": 0}}, {"title": "第7步：将“{{QuestionDir}}”目录下的“图片1”插入到文档的第3段（“当按", "type": "office", "description": "将“{{QuestionDir}}”目录下的“图片1”插入到文档的第3段（“当按说明书……程序的安装”）中，并设置其环绕方式为“四周型”；", "score": {"max": 2, "min": 0}}, {"title": "第8步：将正文第4段分为3栏显示，要求显示分隔线；", "type": "office", "description": "将正文第4段分为3栏显示，要求显示分隔线；", "score": {"max": 2, "min": 0}}, {"title": "第9步：为文档添加页眉，内容为：硬件管理；", "type": "office", "description": "为文档添加页眉，内容为：硬件管理；", "score": {"max": 1, "min": 0}}, {"title": "第10步：将正文最后5段文字转换为表格，列宽为3厘米；", "type": "office", "description": "将正文最后5段文字转换为表格，列宽为3厘米；", "score": {"max": 2, "min": 0}}, {"title": "第11步：设置表格中的所有单元格对齐方式为水平居中（文字在单元格内水平和垂直都居中），表格", "type": "office", "description": "设置表格中的所有单元格对齐方式为水平居中（文字在单元格内水平和垂直都居中），表格页面水平居中显示。设置表格外框线为蓝色（标准色）1.5磅双实线，内框线为蓝色（标准色）0.75磅单实线，表格第1行为红色（标准色）底纹；", "score": {"max": 6, "min": 0}}, {"title": "第12步：在表格前面正文最后一段处绘制一个高度和宽度都为2厘米的“心形”，填充颜色为红色（", "type": "office", "description": "在表格前面正文最后一段处绘制一个高度和宽度都为2厘米的“心形”，填充颜色为红色（标准色），无轮廓。", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

