VALUES ('演示文稿基础操作实训 02', '根据“{{QuestionDir}}”中的“中学生健康饮食.pdf“文件内容新建演示文稿命名为“中学生健康饮食.pptx”，演示文稿文字内容见“健康饮食提纲.docx”文档。', '办公应用基础', 'office', '[{"title": "第1步：根据“健康饮食提纲.docx”中的内容建立幻灯片，并将各幻灯片中的标题和内容分开", "type": "ppt", "description": "根据“健康饮食提纲.docx”中的内容建立幻灯片，并将各幻灯片中的标题和内容分开，幻灯片大小为16:9。", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_02.zip", "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}]}}, {"title": "第2步：在所有幻灯片之前增加一张标题幻灯片，标题为：中学生的健康饮食，副标题为：关注中学", "type": "ppt", "description": "在所有幻灯片之前增加一张标题幻灯片，标题为：中学生的健康饮食，副标题为：关注中学生的身体健康。", "score": {"max": 1, "min": 0}}, {"title": "第3步：将第2张至第11张幻灯片版式更换为“两栏内容”。", "type": "ppt", "description": "将第2张至第11张幻灯片版式更换为“两栏内容”。", "score": {"max": 2, "min": 0}}, {"title": "第4步：根据“{{QuestionDir}}”目录中的“中学生健康饮食.pdf“文件内容", "type": "ppt", "description": "根据“{{QuestionDir}}”目录中的“中学生健康饮食.pdf“文件内容，在每张幻灯片内插入相应图片。", "score": {"max": 4, "min": 0}}, {"title": "第5步：根据样稿设置标题幻灯片中的图片大小及位置。将图片置于底层，艺术效果为“蜡笔平滑”", "type": "ppt", "description": "根据样稿设置标题幻灯片中的图片大小及位置。将图片置于底层，艺术效果为“蜡笔平滑”。将标题文字设置为华文彩云，60磅，文本框填充为“247，221，113“，文本填充颜色为蓝色，文本轮廓颜色为蓝色。标题置于幻灯片左边。副标题使用默认设置，更改其位置。", "score": {"max": 4, "min": 0}}, {"title": "第6步：将第2张幻灯片中的图片样式设置为“柔化边缘椭圆”。", "type": "ppt", "description": "将第2张幻灯片中的图片样式设置为“柔化边缘椭圆”。", "score": {"max": 1, "min": 0}}, {"title": "第7步：将第3张幻灯片中图片与文字的位置互换，将图片样式设置为“矩形投影”。", "type": "ppt", "description": "将第3张幻灯片中图片与文字的位置互换，将图片样式设置为“矩形投影”。", "score": {"max": 1, "min": 0}}, {"title": "第8步：将第4张幻灯片上的文本文本框设置高度为“4.5厘米”，宽度为“22厘米”，并将图", "type": "ppt", "description": "将第4张幻灯片上的文本文本框设置高度为“4.5厘米”，宽度为“22厘米”，并将图片位置自左上角水平为7厘米，垂直为8.2厘米。", "score": {"max": 1, "min": 0}}, {"title": "第9步：将幻灯片背景设置为纯色填充，颜色为“蓝色，强调文字颜色1，淡色80%“。", "type": "ppt", "description": "将幻灯片背景设置为纯色填充，颜色为“蓝色，强调文字颜色1，淡色80%“。", "score": {"max": 1, "min": 0}}, {"title": "第10步：为所有幻灯片设置切换效果：擦除，自右侧，设置自动换片时间为2秒。", "type": "ppt", "description": "为所有幻灯片设置切换效果：擦除，自右侧，设置自动换片时间为2秒。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

