VALUES ('演示文稿基础操作实训 04', '打开“{{QuestionDir}}”下的演示文稿“市场定位分析.pptx”，按照下列要求完成对此文稿的修饰并保存（共20分）', '办公应用基础', 'office', '[{"title": "第1步：使用“角度”主题修饰全文，全部幻灯片切换方案为“百叶窗”。将第1张幻灯片中的标题", "type": "ppt", "description": "使用“角度”主题修饰全文，全部幻灯片切换方案为“百叶窗”。将第1张幻灯片中的标题字体改为“方正粗倩简体”，设置副标题为“楷体”、33磅字，加粗，位置如下图所示。", "score": {"max": 5, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_04.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_04_b001.png"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}, {"type": "master", "desc": "应用了母版/主题", "expected": "true", "score": 5}]}}, {"title": "第2步：将第1张幻灯片版式改为“仅标题”。在白色区域插入矩形：高14厘米，宽25.4厘米", "type": "ppt", "description": "将第1张幻灯片版式改为“仅标题”。在白色区域插入矩形：高14厘米，宽25.4厘米，填充颜色(RGB:253，254，232)，无边框，将矩形置于底层。再插入矩形：高3厘米，宽25.4厘米，填充颜色黑色，将其置于如下图所示位置。", "score": {"max": 5, "min": 0}}, {"title": "第3步：将第2张幻灯片的版式改为“两栏内容”，将第三张幻灯片的文本移到第二张幻灯片左侧，", "type": "ppt", "description": "将第2张幻灯片的版式改为“两栏内容”，将第三张幻灯片的文本移到第二张幻灯片左侧，删除第三张幻灯片。将标题文本框的大小修改为：高2.54厘米，宽25.4厘米，置于幻灯片顶端，形状的效果设置为：细微效果-橙色，强调颜色2。", "score": {"max": 5, "min": 0}}, {"title": "第4步：将第3张幻灯片中的文字转换成“目标图列表”，颜色：彩色-强调文字颜色，样式：三维", "type": "ppt", "description": "将第3张幻灯片中的文字转换成“目标图列表”，颜色：彩色-强调文字颜色，样式：三维优雅，动画效果设置为“进入-螺旋飞入”，效果选项为：一次级别。", "score": {"max": 5, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

