VALUES ('演示文稿基础操作实训 05', '打开“{{QuestionDir}}”下的“智慧城市-杭州”，根据下列要求制作演示文稿。', '办公应用基础', 'office', '[{"title": "第1步：将在第1张幻灯片前插入一张标题幻灯片，输入主标题“智慧城市杭州”，副标题：202", "type": "ppt", "description": "将在第1张幻灯片前插入一张标题幻灯片，输入主标题“智慧城市杭州”，副标题：2024年12月。", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_05.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_05_y001.png", "/api/uploads/practice/演示文稿基础/op_05_y002.png", "/api/uploads/practice/演示文稿基础/op_05_y003.png"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}, {"type": "master", "desc": "应用了母版/主题", "expected": "true", "score": 5}]}}, {"title": "第2步：将第3张的版式改为“比较”，将第4张和第5张幻灯片的内容复制到第3张的两边。然后", "type": "ppt", "description": "将第3张的版式改为“比较”，将第4张和第5张幻灯片的内容复制到第3张的两边。然后删除第4、5张幻灯片。", "score": {"max": 2, "min": 0}}, {"title": "第3步：整个演示文稿使用“奥斯汀”设计主题，主题颜色使用“龙腾四海”。", "type": "ppt", "description": "整个演示文稿使用“奥斯汀”设计主题，主题颜色使用“龙腾四海”。", "score": {"max": 3, "min": 0}}, {"title": "第4步：编辑幻灯片母版：进入幻灯片母版视图，在母版中插入“{{QuestionDir}}", "type": "ppt", "description": "编辑幻灯片母版：进入幻灯片母版视图，在母版中插入“{{QuestionDir}}”下的“杭州LOGO.jpg“图片，对图片进行裁剪，将其空白区域裁剪一部分，再将其缩放至高2.4宽2.9大小，放至下图中所示位置。", "score": {"max": 3, "min": 0}}, {"title": "第5步：通过幻灯片母版为每张幻灯片增加利用艺术字制作的水印效果，水印文字中应包含“智慧城", "type": "ppt", "description": "通过幻灯片母版为每张幻灯片增加利用艺术字制作的水印效果，水印文字中应包含“智慧城市-杭州”字样，并旋转一定的角度。", "score": {"max": 2, "min": 0}}, {"title": "第6步：在第1张幻灯片中插入“{{QuestionDir}}”下的图片“智慧城市.jpg", "type": "ppt", "description": "在第1张幻灯片中插入“{{QuestionDir}}”下的图片“智慧城市.jpg”，删除其背景，将其移动至下图所示位置。", "score": {"max": 2, "min": 0}}, {"title": "第7步：根据第4张幻灯片文字内容创建一个如下图所示的结构图，并使用“彩色范围-强调文字颜", "type": "ppt", "description": "根据第4张幻灯片文字内容创建一个如下图所示的结构图，并使用“彩色范围-强调文字颜色5至6”，强烈效果。并为该结构图添加进入“轮子”动画，4轮辐图案效果。", "score": {"max": 3, "min": 0}}, {"title": "第8步：为演示文稿设置不少于3种幻灯片切换方式。", "type": "ppt", "description": "为演示文稿设置不少于3种幻灯片切换方式。", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

