VALUES ('演示文稿基础操作实训 06', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：设置第1张幻灯片中的“鸟”图片调整叠放次序为“置于底层”；", "type": "ppt", "description": "设置第1张幻灯片中的“鸟”图片调整叠放次序为“置于底层”；", "score": {"max": 1, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_06.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_06_____1.jpg", "/api/uploads/practice/演示文稿基础/op_06_____2.jpg"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}, {"type": "master", "desc": "应用了母版/主题", "expected": "true", "score": 5}]}}, {"title": "第2步：将“{{QuestionDir}}”文件夹下的图片文件“认识生物多样性（背景图片", "type": "ppt", "description": "将“{{QuestionDir}}”文件夹下的图片文件“认识生物多样性（背景图片）.jpg”设置为第2—19张幻灯片的背景；", "score": {"max": 1, "min": 0}}, {"title": "第3步：设置第3张幻灯片中内容为“指地球上生物圈中……”的文本框形状填充为“金色、强调文", "type": "ppt", "description": "设置第3张幻灯片中内容为“指地球上生物圈中……”的文本框形状填充为“金色、强调文字颜色4、淡色80%”，形状轮廓粗细为“1.5磅”，虚线为“短划线”；", "score": {"max": 3, "min": 0}}, {"title": "第4步：设置幻灯片母版中名为“二、生物种类的多样性”的版式，版式的标题字体为黑体，字号为", "type": "ppt", "description": "设置幻灯片母版中名为“二、生物种类的多样性”的版式，版式的标题字体为黑体，字号为36磅，并将第4—8张幻灯片应用于该版式；", "score": {"max": 3, "min": 0}}, {"title": "第5步：在第10张幻灯片中插入“{{QuestionDir}}”文件夹下的图片文件“松鼠", "type": "ppt", "description": "在第10张幻灯片中插入“{{QuestionDir}}”文件夹下的图片文件“松鼠.jpg”，图片大小调整为高6.5厘米，宽7.5厘米，图片样式为“映像圆角矩形”，并将图片放于合适位置；", "score": {"max": 2, "min": 0}}, {"title": "第6步：将第13张幻灯片中的“我国科学家袁隆平院士……”文本框设置字体格式为“楷体或楷体", "type": "ppt", "description": "将第13张幻灯片中的“我国科学家袁隆平院士……”文本框设置字体格式为“楷体或楷体_GB2312”，颜色为“浅蓝（标准色）”，字号为“18”；", "score": {"max": 3, "min": 0}}, {"title": "第7步：将第14张幻灯片中的第2张图片设置为“进入”下的“缩放”动画效果，效果选项为“幻", "type": "ppt", "description": "将第14张幻灯片中的第2张图片设置为“进入”下的“缩放”动画效果，效果选项为“幻灯片中心”；", "score": {"max": 2, "min": 0}}, {"title": "第8步：在第19张幻灯片中合适位置插入一个“动作按钮：第一张”，鼠标移过时超链接到第1张", "type": "ppt", "description": "在第19张幻灯片中合适位置插入一个“动作按钮：第一张”，鼠标移过时超链接到第1张幻灯片；", "score": {"max": 2, "min": 0}}, {"title": "第9步：给第19张幻灯片添加备注，内容为“生物多样性是人类生存和发展、人与自然和谐共生的", "type": "ppt", "description": "给第19张幻灯片添加备注，内容为“生物多样性是人类生存和发展、人与自然和谐共生的重要基础。”；", "score": {"max": 1, "min": 0}}, {"title": "第10步：设置第2—19幻灯片的切换效果为“华丽型”下的“立方体”，效果选项为“自左侧”。", "type": "ppt", "description": "设置第2—19幻灯片的切换效果为“华丽型”下的“立方体”，效果选项为“自左侧”。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

