VALUES ('演示文稿基础操作实训 08', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：将“{{QuestionDir}}”文件夹下的图片文件“背景.jpg”设置为第1", "type": "ppt", "description": "将“{{QuestionDir}}”文件夹下的图片文件“背景.jpg”设置为第1张、第2张和第7张幻灯片背景；", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_08.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_08_____1.jpg", "/api/uploads/practice/演示文稿基础/op_08_____2.jpg"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}, {"type": "master", "desc": "应用了母版/主题", "expected": "true", "score": 5}]}}, {"title": "第2步：设置第1张幻灯片中的夏至图片旋转“10”度，进入动画效果为“玩具风车”；", "type": "ppt", "description": "设置第1张幻灯片中的夏至图片旋转“10”度，进入动画效果为“玩具风车”；", "score": {"max": 2, "min": 0}}, {"title": "第3步：在第2张幻灯片中插入横排文本框，输入内容为“节气特点”，设置文本的字体为“微软雅", "type": "ppt", "description": "在第2张幻灯片中插入横排文本框，输入内容为“节气特点”，设置文本的字体为“微软雅黑”、字号为“72”、字体样式为“加粗”，颜色为RGB（红色：48，绿色：106，蓝色：51）；", "score": {"max": 6, "min": 0}}, {"title": "第4步：将第10张幻灯片中的“节气风俗”文本框设置超链接，鼠标移过时链接到第2张幻灯片；", "type": "ppt", "description": "将第10张幻灯片中的“节气风俗”文本框设置超链接，鼠标移过时链接到第2张幻灯片；", "score": {"max": 1, "min": 0}}, {"title": "第5步：删除最后一张空白幻灯片；", "type": "ppt", "description": "删除最后一张空白幻灯片；", "score": {"max": 1, "min": 0}}, {"title": "第6步：在版式名称为“Office 主题”的母版上插入“{{QuestionDir}}”", "type": "ppt", "description": "在版式名称为“Office 主题”的母版上插入“{{QuestionDir}}”文件夹下的图片“夏季节气.png”，并设置图片自左上角水平位置为“23厘米”，垂直位置为“17厘米”；", "score": {"max": 6, "min": 0}}, {"title": "第7步：设置所有幻灯片的切换效果为“细微型”下的“淡出”，自动换片的时间为“8秒”。", "type": "ppt", "description": "设置所有幻灯片的切换效果为“细微型”下的“淡出”，自动换片的时间为“8秒”。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

