VALUES ('演示文稿基础操作实训 09', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：设置第1张上的“珍稀动物图鉴”文本框的文本填充为“橙色”，文本轮廓为“橙色，强调", "type": "ppt", "description": "设置第1张上的“珍稀动物图鉴”文本框的文本填充为“橙色”，文本轮廓为“橙色，强调文字颜色2，深色25%”，文本效果为转换下的“波形1”；", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_09.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_09_____1.jpg", "/api/uploads/practice/演示文稿基础/op_09_____2.jpg", "/api/uploads/practice/演示文稿基础/op_09_____3.jpg"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "slide_count", "desc": "幻灯片数量不少于3张", "expected": "3", "score": 5}]}}, {"title": "第2步：在第1张幻灯片中插入“{{QuestionDir}}”目录下的音频“音乐.mp3", "type": "ppt", "description": "在第1张幻灯片中插入“{{QuestionDir}}”目录下的音频“音乐.mp3”，开始方式为“自动”，并设置音量为“中”，放映时隐藏；", "score": {"max": 4, "min": 0}}, {"title": "第3步：在第2张幻灯片右侧插入形状下的“云形”，输入文本“全世界野生大熊猫不足1600只", "type": "ppt", "description": "在第2张幻灯片右侧插入形状下的“云形”，输入文本“全世界野生大熊猫不足1600只，属于中国国家一级保护动物”，形状大小为“高度7.5厘米、宽度10.5厘米”，并给“云形”设置形状效果为棱台（顶端）下的“斜面”；", "score": {"max": 5, "min": 0}}, {"title": "第4步：设置第3张幻灯片的版式为“空白”，并将带有“中国·四川”字样的图片置于顶层；", "type": "ppt", "description": "设置第3张幻灯片的版式为“空白”，并将带有“中国·四川”字样的图片置于顶层；", "score": {"max": 2, "min": 0}}, {"title": "第5步：将第6张幻灯片中的3张白鹮图片组合成一张图片；", "type": "ppt", "description": "将第6张幻灯片中的3张白鹮图片组合成一张图片；", "score": {"max": 2, "min": 0}}, {"title": "第6步：给第9张幻灯片添加备注，内容为“动物是人类的朋友，请保护动物”；", "type": "ppt", "description": "给第9张幻灯片添加备注，内容为“动物是人类的朋友，请保护动物”；", "score": {"max": 2, "min": 0}}, {"title": "第7步：将第10张幻灯片老虎图片的格式重设，并取消该幻灯片编号。", "type": "ppt", "description": "将第10张幻灯片老虎图片的格式重设，并取消该幻灯片编号。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"},