VALUES ('演示文稿基础操作实训 14', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：将第1张幻灯片与第2张幻灯片的位置调换；", "type": "ppt", "description": "将第1张幻灯片与第2张幻灯片的位置调换；", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_14.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_14_____1.png"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}]}}, {"title": "第2步：在第1张幻灯片中插入“{{QuestionDir}}”目录下的音频文件“音乐.m", "type": "ppt", "description": "在第1张幻灯片中插入“{{QuestionDir}}”目录下的音频文件“音乐.mp3”，并设置放映时隐藏；", "score": {"max": 2, "min": 0}}, {"title": "第3步：选择第2张幻灯片，设置标题“目录”字体格式为“54磅、幼圆、加粗、阴影”；", "type": "ppt", "description": "选择第2张幻灯片，设置标题“目录”字体格式为“54磅、幼圆、加粗、阴影”；", "score": {"max": 4, "min": 0}}, {"title": "第4步：将第3张幻灯片上的三张图片进行组合；", "type": "ppt", "description": "将第3张幻灯片上的三张图片进行组合；", "score": {"max": 2, "min": 0}}, {"title": "第5步：选择第5张幻灯片，将“{{QuestionDir}}”下的图片“车水号子.jpg", "type": "ppt", "description": "选择第5张幻灯片，将“{{QuestionDir}}”下的图片“车水号子.jpg”设置为第一张自选图形的填充效果，给这个自选图形添加“白色，背景1”、“3磅”边框线，设置其形状效果阴影下的“居中偏移”，并设置强调动画效果为“陀螺旋”；", "score": {"max": 5, "min": 0}}, {"title": "第6步：设置所有幻灯片切换方式为“揭开”，持续时间为“2秒”；", "type": "ppt", "description": "设置所有幻灯片切换方式为“揭开”，持续时间为“2秒”；", "score": {"max": 2, "min": 0}}, {"title": "第7步：选择第7张幻灯片，插入“{{QuestionDir}}”下的图片“返回.gif”", "type": "ppt", "description": "选择第7张幻灯片，插入“{{QuestionDir}}”下的图片“返回.gif”，修改图片缩放比例为30%，将图片拖放至幻灯片右下角，并给图片添加超链接，链接到第1张幻灯片。（3分）请参看样张：样张1", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description":