VALUES ('演示文稿基础操作实训 18', '打开“{{QuestionDir}}”下的“中国电动汽车发展历程.pptx”，按下列要求制作演示文稿。', '办公应用基础', 'office', '[{"title": "第1步：打开幻灯片母版视图，将“{{QuestionDir}}”下的“2-5.ppt”作", "type": "ppt", "description": "打开幻灯片母版视图，将“{{QuestionDir}}”下的“2-5.ppt”作为主题应用到本演示文稿中。", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_18.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_18_y001.png"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}, {"type": "master", "desc": "应用了母版/主题", "expected": "true", "score": 5}]}}, {"title": "第2步：标题幻灯片母版：主标题文字：微软雅黑，加粗，50磅，黄色。副标题：黑体，36磅，", "type": "ppt", "description": "标题幻灯片母版：主标题文字：微软雅黑，加粗，50磅，黄色。副标题：黑体，36磅，加粗，白色。", "score": {"max": 2, "min": 0}}, {"title": "第3步：其余幻灯片母版：标题文字：黑体，32号，加粗，白色。内容占位符中一级文本大小为2", "type": "ppt", "description": "其余幻灯片母版：标题文字：黑体，32号，加粗，白色。内容占位符中一级文本大小为28磅，二级为24磅。其余设置不变。", "score": {"max": 2, "min": 0}}, {"title": "第4步：将第1张幻灯片改为标题幻灯片，第2张幻灯片的内容文字设置为32磅。第4张幻灯片设", "type": "ppt", "description": "将第1张幻灯片改为标题幻灯片，第2张幻灯片的内容文字设置为32磅。第4张幻灯片设为“比较”，删除文字“展示相关技术研究数据图表或早期电动汽车实验车型图片。”，分别插入“{{QuestionDir}}”文件夹中的“比亚迪秦2015.jpg”与“奇瑞2015.jpg”，并在上方添加相应说明文字分别为“比亚迪秦2015、奇瑞2015”。裁剪图片，使两张图片等高。", "score": {"max": 2, "min": 0}}, {"title": "第5步：显示每张幻灯片编号，首页不显示。", "type": "ppt", "description": "显示每张幻灯片编号，首页不显示。", "score": {"max": 2, "min": 0}}, {"title": "第6步：为第二张幻灯片添加超链接，链接对应的幻灯片，如下表所示：", "type": "ppt", "description": "为第二张幻灯片添加超链接，链接对应的幻灯片，如下表所示：", "score": {"max": 2, "min": 0}}, {"title": "第7步：为第3至19张幻灯片添加动作按钮，将该动作按钮链接到第2张(目录)幻灯片。", "type": "ppt", "description": "为第3至19张幻灯片添加动作按钮，将该动作按钮链接到第2张(目录)幻灯片。", "score": {"max": 2, "min": 0}}, {"title": "第8步：为第14张幻灯片中的“2024年中国私人充电桩行业市场规模、进入壁垒及投资战略研", "type": "ppt", "description": "为第14张幻灯片中的“2024年中国私人充电桩行业市场规模、进入壁垒及投资战略研究”添加超链接，链接到网址：https://www.163.com/dy/article/JCP1GGHR0552SV13.html。", "score": {"max": 1, "min": 0}}, {"title": "第9步：将最后一张幻灯片版式设为“空白”，为“感谢观看与聆听!”设置一种艺术字样式，并改", "type": "ppt", "description": "将最后一张幻灯片版式设为“空白”，为“感谢观看与聆听!”设置一种艺术字样式，并改变字体大小和位置，并为该文字设置“浮出”退出效果，在上一动画之后开始。", "score": {"max": 2, "min": 0}}, {"title": "第10步：为所有幻灯片设置切换效果：“揭开”，持续时间1秒，声音：风声。", "type": "ppt", "description": "为所有幻灯片设置切换效果：“揭开”，持续时间1秒，声音：风声。", "score": {"max": 1, "min": 0}}, {"title": "第11步：设置自定义放映：放映名称：“我的放映”，放映第1、3、5、7、10、13、15、", "type": "ppt", "description": "设置自定义放映：放映名称：“我的放映”，放映第1、3、5、7、10、13、15、17、20张幻灯片。", "score": {"max": 2, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

