VALUES ('演示文稿基础操作实训 34', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：将第2张幻灯片中的“小满，是二十四节气之……”文本框设置字体格式为“倾斜”，颜色", "type": "ppt", "description": "将第2张幻灯片中的“小满，是二十四节气之……”文本框设置字体格式为“倾斜”，颜色为“浅蓝（标准色）”，字号为“24”，行距设置为1.5倍行距；", "score": {"max": 4, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_34.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_34_____1.jpg", "/api/uploads/practice/演示文稿基础/op_34_____2.jpg"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "transition", "desc": "包含幻灯片切换效果", "expected": "true", "score": 5}]}}, {"title": "第2步：在第3张幻灯片右侧绘制“平行四边形”，调整至合适大小和位置，设置平行四边形的填充", "type": "ppt", "description": "在第3张幻灯片右侧绘制“平行四边形”，调整至合适大小和位置，设置平行四边形的填充图片为“{{QuestionDir}}”目录下的“立秋.jpg”，动画效果为“进入-棋盘”，开始为“上一动画之后”；", "score": {"max": 4, "min": 0}}, {"title": "第3步：在第4张幻灯片中插入“{{QuestionDir}}”下的图片“稻草人.png”", "type": "ppt", "description": "在第4张幻灯片中插入“{{QuestionDir}}”下的图片“稻草人.png”，设置图片的位置为“水平4.1厘米，垂直3.09厘米，度量依据都为左上角”；", "score": {"max": 3, "min": 0}}, {"title": "第4步：在第5张幻灯片中，删除文本框“我国古代将小满分……”超链接，并更改“小满的特点”", "type": "ppt", "description": "在第5张幻灯片中，删除文本框“我国古代将小满分……”超链接，并更改“小满的特点”文本框文字旋转“0°”；", "score": {"max": 2, "min": 0}}, {"title": "第5步：设置第6张上的“山坡”图片饱和度为“100%”，色调为“6500K”；", "type": "ppt", "description": "设置第6张上的“山坡”图片饱和度为“100%”，色调为“6500K”；", "score": {"max": 2, "min": 0}}, {"title": "第6步：设置第7张幻灯片右边“小满”图片效果为“阴影-左上对角透视”；", "type": "ppt", "description": "设置第7张幻灯片右边“小满”图片效果为“阴影-左上对角透视”；", "score": {"max": 2, "min": 0}}, {"title": "第7步：设置所有幻灯片的切换效果为“华丽型”下的“涟漪”，效果选项为“从左上部”，放映类", "type": "ppt", "description": "设置所有幻灯片的切换效果为“华丽型”下的“涟漪”，效果选项为“从左上部”，放映类型为“观众自行浏览(窗口)”。", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

