VALUES ('演示文稿基础操作实训 35', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：设置第1张幻灯片背景为“纹理”下的“水滴”，不改变其它幻灯片背景；", "type": "ppt", "description": "设置第1张幻灯片背景为“纹理”下的“水滴”，不改变其它幻灯片背景；", "score": {"max": 3, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_35.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_35_____1.jpg"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "slide_count", "desc": "幻灯片数量不少于3张", "expected": "3", "score": 5}]}}, {"title": "第2步：设置第2张幻灯片中的“1993年1月18日，第四……”文本框形状填充颜色为“黄色", "type": "ppt", "description": "设置第2张幻灯片中的“1993年1月18日，第四……”文本框形状填充颜色为“黄色（标准色）”，形状轮廓为“红色（标准色）”，文本效果为发光：“灰色-50%，5pt发光，强调文字颜色3”；", "score": {"max": 3, "min": 0}}, {"title": "第3步：将第4张幻灯片上的图片（内容是水龙头在放水）设置缩放高度和宽度为“100%”；", "type": "ppt", "description": "将第4张幻灯片上的图片（内容是水龙头在放水）设置缩放高度和宽度为“100%”；", "score": {"max": 2, "min": 0}}, {"title": "第4步：设置第6张幻灯片上的图片（内容是蘑菇屋和树）亮度为“20%”，对比度为“-40%", "type": "ppt", "description": "设置第6张幻灯片上的图片（内容是蘑菇屋和树）亮度为“20%”，对比度为“-40%”，图片样式为“圆形对角，白色”；", "score": {"max": 4, "min": 0}}, {"title": "第5步：给第7张幻灯片插入“{{QuestionDir}}”下的“节约用水.mp4”视频", "type": "ppt", "description": "给第7张幻灯片插入“{{QuestionDir}}”下的“节约用水.mp4”视频，音量调整为“静音”，并移动到合适位置；", "score": {"max": 2, "min": 0}}, {"title": "第6步：设置第8张幻灯片上的图片（水龙头正在放水）调整叠放次序，置于底层；", "type": "ppt", "description": "设置第8张幻灯片上的图片（水龙头正在放水）调整叠放次序，置于底层；", "score": {"max": 3, "min": 0}}, {"title": "第7步：在幻灯片最后插入一张幻灯片，版式设为“仅标题”、标题文字为“谢谢观看！”。", "type": "ppt", "description": "在幻灯片最后插入一张幻灯片，版式设为“仅标题”、标题文字为“谢谢观看！”。", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

