VALUES ('演示文稿基础操作实训 40', '请在打开的PowerPoint的演示文稿中，进行下列操作，完成操作后，请保存文件，并关闭PowerPoint。', '办公应用基础', 'office', '[{"title": "第1步：为所有幻灯片设置“顶峰”主题", "type": "ppt", "description": "为所有幻灯片设置“顶峰”主题", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/演示文稿基础/op_40.pptx", "sampleImages": ["/api/uploads/practice/演示文稿基础/op_40_o-PowerPoint-Ppt-30010_Title0.png"], "config": {"checkpoints": [{"type": "slide_count", "desc": "幻灯片数量不少于5张", "expected": "5", "score": 5}, {"type": "animation", "desc": "包含动画效果", "expected": "true", "score": 8}, {"type": "master", "desc": "应用了母版/主题", "expected": "true", "score": 5}]}}, {"title": "第2步：在演示文稿的第1张幻灯片前插入一张幻灯片。应用“标题幻灯片”版式，标题文本为“W", "type": "ppt", "description": "在演示文稿的第1张幻灯片前插入一张幻灯片。应用“标题幻灯片”版式，标题文本为“WORD应用讲座”（见样张1）", "score": {"max": 3, "min": 0}}, {"title": "第3步：第3张幻灯片的标题文本设置“飞入”进入动画，效果为“自左上部”，再添加一个强调动", "type": "ppt", "description": "第3张幻灯片的标题文本设置“飞入”进入动画，效果为“自左上部”，再添加一个强调动画为“跷跷板”，两个动画自动连续播放（见样张2）", "score": {"max": 5, "min": 0}}, {"title": "第4步：在最后一张幻灯片的右下角添加“后退或前一项”动作按钮，并超链接到第1张幻灯片。动", "type": "ppt", "description": "在最后一张幻灯片的右下角添加“后退或前一项”动作按钮，并超链接到第1张幻灯片。动作按钮套用“细微效果-淡紫，强调颜色6”的形状样式，高度和宽度均设置为1.5厘米", "score": {"max": 4, "min": 0}}, {"title": "第5步：设置演示文稿所有幻灯片的换片方式为“推进”，效果为“自左侧”，持续时间为“2秒”", "type": "ppt", "description": "设置演示文稿所有幻灯片的换片方式为“推进”，效果为“自左侧”，持续时间为“2秒”", "score": {"max": 3, "min": 0}}, {"title": "第6步：利用幻灯片母版，使每张幻灯片右上角都显示“{{QuestionDir}}”下的“", "type": "ppt", "description": "利用幻灯片母版，使每张幻灯片右上角都显示“{{QuestionDir}}”下的“图片2.jpg”，图片大小为高度3厘米，宽度4厘米（见样张3）。请参看样张：样张1样张2样张3", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

-- 电子表格基础 - 自动评分: 是 (4个检查点)
VALUES ('电子表格基础操作实训 01', '【电子表格题】 打开电子表格“职工档案表.xlsx“，按下列要求，对表格进行格式化，并对数据进行处理。', '办公应用基础', 'excel', '[{"title": "第1步：将Sheet1表重命名为“员工信息”，将工作表标签设置为“标准色橙色”；", "type": "excel", "description": "将Sheet1表重命名为“员工信息”，将工作表标签设置为“标准色橙色”；", "score": {"max": 2, "min": 0}, "resourceFile": "/api/uploads/practice/电子表格基础/op_01.xlsx", "sampleImages": ["/api/uploads/practice/电子表格基础/op_01_y001.png"], "config": {"checkpoints": [{"type": "value", "desc": "工作表''“员工信息”''存在（验证A1单元格）", "target": "“员工信息”!A1", "expected": "*", "score": 5}, {"type": "format", "desc": "存在合并单元格", "target": "A1", "expected": "merge", "score": 5}, {"type": "format", "desc": "设置了边框", "target": "A2", "expected": "border", "score": 5}, {"type": "format", "desc": "标题加粗显示", "target": "A1", "expected": "bold", "score": 3}]}}, {"title": "第2步：为“员工信息“表中序号列添加如“001，002”的序列数字；", "type": "excel", "description": "为“员工信息“表中序号列添加如“001，002”的序列数字；", "score": {"max": 2, "min": 0}}, {"title": "第3步：将“出生年月“一列的格式设置为如“1999-01-01”的格式；", "type": "excel", "description": "将“出生年月“一列的格式设置为如“1999-01-01”的格式；", "score": {"max": 3, "min": 0}}, {"title": "第4步：将“性别”一列F3:F20单元格区域的数据有效性设置为只能输入“男”或“女”；", "type": "excel", "description": "将“性别”一列F3:F20单元格区域的数据有效性设置为只能输入“男”或“女”；", "score": {"max": 3, "min": 0}}, {"title": "第5步：在“年龄”一列计算每位员工今年的年龄；", "type": "excel", "description": "在“年龄”一列计算每位员工今年的年龄；", "score": {"max": 3, "min": 0}}, {"title": "第6步：在“退休年限”一列计算各员工离退休还有多少年，男性60岁退休，女性55岁退休；", "type": "excel", "description": "在“退休年限”一列计算各员工离退休还有多少年，男性60岁退休，女性55岁退休；", "score": {"max": 3, "min": 0}}, {"title": "第7步：在“员工信息”表中，将A1:H1单元格合并后居中，将字体设置为“微软雅黑，加粗，", "type": "excel", "description": "在“员工信息”表中，将A1:H1单元格合并后居中，将字体设置为“微软雅黑，加粗，24磅“。表格第1行行高为40；", "score": {"max": 2, "min": 0}}, {"title": "第8步：表头区域A2:H2，设置为“微软雅黑，14，行高22”。其余数据区域设置为“宋体", "type": "excel", "description": "表头区域A2:H2，设置为“微软雅黑，14，行高22”。其余数据区域设置为“宋体，12，行高20”。各列除D列列宽为15，其余各列列宽均为10，设置区域A2:H20水平、垂直均居中；", "score": {"max": 3, "min": 0}}, {"title": "第9步：给数据区域A2:H20添加边框:内边框细实线，外边框粗实线（线条样式表中右边第5", "type": "excel", "description": "给数据区域A2:H20添加边框:内边框细实线，外边框粗实线（线条样式表中右边第5个）；", "score": {"max": 2, "min": 0}}, {"title": "第10步：页面设置:将纸张方向设置为纵向，左右页边距均为1.3，水平居中打印，将第2行设置", "type": "excel", "description": "页面设置:将纸张方向设置为纵向，左右页边距均为1.3，水平居中打印，将第2行设置为打印标题行；", "score": {"max": 2, "min": 0}}, {"title": "第11步：将“员工信息”表复制一份，更名为“汇总表”，将“汇总表”标签颜色改为“标准色绿色", "type": "excel", "description": "将“员工信息”表复制一份，更名为“汇总表”，将“汇总表”标签颜色改为“标准色绿色”。以分类汇总的方法统计各部门的人数；", "score": {"max": 5, "min": 0}}, {"title": "第12步：将Sheet2表格更名为“数据透视”，以“员工信息”表为数据源，在“数据透视”表", "type": "excel", "description": "将Sheet2表格更名为“数据透视”，以“员工信息”表为数据源，在“数据透视”表中A1单元格开始建立数据透视表，统计各部门男女人数。统计结果如下图所示：", "score": {"max": 5, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

