VALUES ('电子表格基础操作实训 14', '请在打开的EXCEL的电子表格中，进行下列操作，完成操作后，请保存文件，并关闭EXCEL。', '办公应用基础', 'excel', '[{"title": "第1步：将表格标题“A公司五月份保险明细”的字体格式设置为：仿宋或仿宋_GB2312，1", "type": "excel", "description": "将表格标题“A公司五月份保险明细”的字体格式设置为：仿宋或仿宋_GB2312，14磅，并设置“A1:I1”单元格区域对齐方式为：跨列居中，“A2:I17”单元格区域对齐方式为：水平垂直均居中；", "score": {"max": 5, "min": 0}, "resourceFile": "/api/uploads/practice/电子表格基础/op_14.xlsx", "sampleImages": ["/api/uploads/practice/电子表格基础/op_14_____1.png", "/api/uploads/practice/电子表格基础/op_14_____2.png"], "config": {"checkpoints": [{"type": "format", "desc": "设置了边框", "target": "A2", "expected": "border", "score": 5}, {"type": "format", "desc": "设置了数字/货币格式", "target": "B3", "expected": "number", "score": 5}, {"type": "value", "desc": "A1单元格有内容（标题）", "target": "A1", "expected": "*", "score": 2}]}}, {"title": "第2步：设置“A2:I17”单元格区域的内外边框线为红色、细实线；", "type": "excel", "description": "设置“A2:I17”单元格区域的内外边框线为红色、细实线；", "score": {"max": 4, "min": 0}}, {"title": "第3步：利用公式计算每个人实发工资金额（实发工资=基本工资+津贴+奖金-扣款）；", "type": "excel", "description": "利用公式计算每个人实发工资金额（实发工资=基本工资+津贴+奖金-扣款）；", "score": {"max": 3, "min": 0}}, {"title": "第4步：利用函数计算每个人应交保险金额（实发工资≥8000，按实发工资2%交，实发工资≥", "type": "excel", "description": "利用函数计算每个人应交保险金额（实发工资≥8000，按实发工资2%交，实发工资≥5000，按实发工资1%交，实发工资<5000，按实发工资0.5%交），并设置应交保险单元格区域数字类型为：货币形式，货币符号为：￥，小数位数：0；", "score": {"max": 6, "min": 0}}, {"title": "第5步：利用函数计算男生人数放在D16单元格，女生人数放在D17单元格；", "type": "excel", "description": "利用函数计算男生人数放在D16单元格，女生人数放在D17单元格；", "score": {"max": 6, "min": 0}}, {"title": "第6步：新建一个工作表，修改工作表名称为：分类汇总，将“Sheet1”工作表中“A2:I", "type": "excel", "description": "新建一个工作表，修改工作表名称为：分类汇总，将“Sheet1”工作表中“A2:I15”单元格区域复制到新工作表A1单元格处；", "score": {"max": 3, "min": 0}}, {"title": "第7步：在“分类汇总”工作表中按部门汇总“实发工资”和“应交保险”总和（按部门升序排序）", "type": "excel", "description": "在“分类汇总”工作表中按部门汇总“实发工资”和“应交保险”总和（按部门升序排序）；", "score": {"max": 4, "min": 0}}, {"title": "第8步：参照样张，以“Sheet1”工作表为基础（数据区域A2:I15）建立数据透视表放", "type": "excel", "description": "参照样张，以“Sheet1”工作表为基础（数据区域A2:I15）建立数据透视表放在本表的A20单元格处：统计各个部门按性别应交保险和。", "score": {"max": 4, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

