VALUES ('电子表格基础操作实训 15', '请在打开的EXCEL的电子表格中，进行下列操作，完成操作后，请保存文件，并关闭EXCEL。', '办公应用基础', 'excel', '[{"title": "第1步：设置标题字体格式为“华文行楷，取消加粗”；", "type": "excel", "description": "设置标题字体格式为“华文行楷，取消加粗”；", "score": {"max": 6, "min": 0}, "resourceFile": "/api/uploads/practice/电子表格基础/op_15.xlsx", "sampleImages": ["/api/uploads/practice/电子表格基础/op_15_____1.jpg", "/api/uploads/practice/电子表格基础/op_15_____2.jpg", "/api/uploads/practice/电子表格基础/op_15_____3.jpg"], "config": {"checkpoints": [{"type": "formula", "desc": "使用了IF函数", "target": "B10", "expected": "IF", "score": 8}, {"type": "format", "desc": "标题加粗显示", "target": "A1", "expected": "bold", "score": 3}, {"type": "format", "desc": "设置了数字/货币格式", "target": "B3", "expected": "number", "score": 5}]}}, {"title": "第2步：设置表格第一行的行高为32，其余行行高为17；", "type": "excel", "description": "设置表格第一行的行高为32，其余行行高为17；", "score": {"max": 4, "min": 0}}, {"title": "第3步：请选择所有列，删除“Sheet1”工作表中的重复项；", "type": "excel", "description": "请选择所有列，删除“Sheet1”工作表中的重复项；", "score": {"max": 3, "min": 0}}, {"title": "第4步：使用条件格式：将“D3:D23”内销售额小于10000的单元格，设置为“绿填充色", "type": "excel", "description": "使用条件格式：将“D3:D23”内销售额小于10000的单元格，设置为“绿填充色深绿色文本”；", "score": {"max": 3, "min": 0}}, {"title": "第5步：在F2单元格中输入“实发工资”，用IF函数计算该列的值（计算方法：如果“销售额”", "type": "excel", "description": "在F2单元格中输入“实发工资”，用IF函数计算该列的值（计算方法：如果“销售额”大于15000则用“奖金”列的值加580，如果“销售额”不大于15000但大于10000的则用“奖金”列的值加420，否则用“奖金”列的值加260），结果填入相应单元格内容；", "score": {"max": 6, "min": 0}}, {"title": "第6步：在“Sheet2”工作表中设置“A2:H2”单元格的对齐方式为：水平垂直均居中，", "type": "excel", "description": "在“Sheet2”工作表中设置“A2:H2”单元格的对齐方式为：水平垂直均居中，填充颜色为“橙色，强调文字颜色2，淡色80%”；", "score": {"max": 6, "min": 0}}, {"title": "第7步：在“Sheet2”工作表中利用LEFT函数和RIGHT函数计算“编号”列（计算方", "type": "excel", "description": "在“Sheet2”工作表中利用LEFT函数和RIGHT函数计算“编号”列（计算方法：“代码”中左边取两位，右边取两位），结果填入相应单元格内容；", "score": {"max": 4, "min": 0}}, {"title": "第8步：以“Sheet3”工作表中的“A1:B3”作为条件区域，将“Sheet2”工作表", "type": "excel", "description": "以“Sheet3”工作表中的“A1:B3”作为条件区域，将“Sheet2”工作表中“奖金”大于1300或“实发工资”大于1700的数据复制到“Sheet3”工作表D5开始的区域中。", "score": {"max": 3, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

