VALUES ('电子表格基础操作实训 17', '【电子表格题】 打开考生文件夹下的“Excel.xlsx”，根据下列要求对电子表格进行处理。', '办公应用基础', 'excel', '[{"title": "第1步：删除表格第2行；", "type": "excel", "description": "删除表格第2行；", "score": {"max": 1, "min": 0}, "resourceFile": "/api/uploads/practice/电子表格基础/op_17.xlsx", "sampleImages": ["/api/uploads/practice/电子表格基础/op_17_y001.png"], "config": {"checkpoints": [{"type": "formula", "desc": "使用了VLOOKUP函数", "target": "B10", "expected": "VLOOKUP", "score": 8}, {"type": "format", "desc": "存在合并单元格", "target": "A1", "expected": "merge", "score": 5}, {"type": "format", "desc": "设置了边框", "target": "A2", "expected": "border", "score": 5}, {"type": "format", "desc": "标题加粗显示", "target": "A1", "expected": "bold", "score": 3}, {"type": "chart", "desc": "创建了图表", "target": "Sheet1", "expected": "chart", "score": 10}]}}, {"title": "第2步：将“销售统计”表中的“定价”与“活动价”列数值的格式设为会计专用、保留2位小数；", "type": "excel", "description": "将“销售统计”表中的“定价”与“活动价”列数值的格式设为会计专用、保留2位小数；", "score": {"max": 2, "min": 0}}, {"title": "第3步：对数据表“销售统计”进行适当的格式化，操作如下:合并A1:F1单元格，将标题““", "type": "excel", "description": "对数据表“销售统计”进行适当的格式化，操作如下:合并A1:F1单元格，将标题““双12”图书销售情况统计表\\"设置为华文仿宋、24磅、加粗、深蓝色，并为其填充图案颜色为“橙色,强调文字颜色6,淡色40%”，图案样式为“细逆对角线条纹”；", "score": {"max": 6, "min": 0}}, {"title": "第4步：将单元格区域A2:F2区域的字体设置为微软雅黑、13磅、黄色，居中对齐，并为其填", "type": "excel", "description": "将单元格区域A2:F2区域的字体设置为微软雅黑、13磅、黄色，居中对齐，并为其填充红色（RGB:255,80,80）底纹；", "score": {"max": 4, "min": 0}}, {"title": "第5步：将单元格区域A3:F14区域的字体设置为幼圆、灰色-80%（RGB:95,95,", "type": "excel", "description": "将单元格区域A3:F14区域的字体设置为幼圆、灰色-80%（RGB:95,95,95），居中对齐，并为其填充浅绿色（RGB:204,255,204）底纹；", "score": {"max": 4, "min": 0}}, {"title": "第6步：为单元格区域A2:F14区域设置外边框为深蓝色粗实线（线条样式表中右边第6个），", "type": "excel", "description": "为单元格区域A2:F14区域设置外边框为深蓝色粗实线（线条样式表中右边第6个），内部横向框线为中粗实线（线条样式表中右边第5个），内部竖向框线设置为双实线，颜色均为紫色；", "score": {"max": 3, "min": 0}}, {"title": "第7步：将工作表“销量”中的区域B3:E16定义名称为“销量信息”。在“销售统计”表中的", "type": "excel", "description": "将工作表“销量”中的区域B3:E16定义名称为“销量信息”。在“销售统计”表中的“销量”列右侧增加一列“销售额”，根据“销售额=销量×活动价”构建公式计算出各类图书的销售额。要求在公式中通过VLOOKUP函数自动在工作表“销量”中查找相关商品的具体销量。并在公式中引用所定义的名称“销量信息”；", "score": {"max": 9, "min": 0}}, {"title": "第8步：为“销售统计”表中销售量数据创建饼图，设置数据标签显示在外侧，将图表的标题改为“", "type": "excel", "description": "为“销售统计”表中销售量数据创建饼图，设置数据标签显示在外侧，将图表的标题改为““双12”图书销量统计”，并对数据标签进行设置:数据标签显示为百分比，显示引导线，放置于数据标签外，标签中包括图例项标示。如下图所示：", "score": {"max": 6, "min": 0}}]', '[{"dimension": "process_quality", "dimensionLabel": "操作过程", "weight": 0.4, "sortOrder": 0, "criteria": [{"level": 0, "label": "未完成", "description": "未提交或完成度不足30%"}, {"level": 1, "label": "起步", "description": "能进行基本操作，步骤较生疏"}, {"level": 2, "label": "发展中", "description": "操作基本正确，步骤较完整"}, {"level": 3, "label": "合格", "description": "操作规范，步骤完整"}, {"level": 4, "label": "良好", "description": "操作熟练，效率较高"}, {"level": 5, "label": "优秀", "description": "操作娴熟，有技巧性"}]}, {"dimension": "product_result", "dimensionLabel": "作品成果", "weight": 0.6, "sortOrder": 1, "criteria": [{"level": 0, "label": "未提交", "description": "未提交最终作品"}, {"level": 1, "label": "不合格", "description": "成果存在严重错误"}, {"level": 2, "label": "基本合格", "description": "成果基本完整，有少量错误"}, {"level": 3, "label": "合格", "description": "成果完整，符合要求"}, {"level": 4, "label": "良好", "description": "成果质量较好，细节到位"}, {"level": 5, "label": "优秀", "description": "成果精美，可作为范例"}]}]', 'DUAL_DIMENSION', 'SYSTEM', 0);

