INSERT INTO question_bank (category_id, subject, question_type, question_text, options, correct_answer, explanation, difficulty_level, created_by, status, school_id, stage_id, create_time, update_time) VALUES
(@n42, '信息技术应用基础', 'SINGLE_CHOICE', '以下哪个操作系统类型主要用于管理网络中的资源和通信（）。', '["桌面操作系统", "网络操作系统", "移动操作系统", "服务器操作系统"]', 'B', NULL, 2, @admin_user_id, 1, 1, 4, NOW(), NOW()),
